actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate MS state additions
            double additions = 0.0;

            // MS requires addback of:
            // - Federal interest income (taxable to MS)
            // - IRC 199A deduction (MS may not conform)
            // - State income taxes deducted federally
            // - Certain bonus depreciation amounts (depends on year)

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.section_199a_deduction;
            // additions += result.state_taxes_deducted;

            apportionment.state_additions = additions;

            // Calculate MS state subtractions
            double subtractions = 0.0;

            // MS allows subtraction of:
            // - MS municipal bond interest (exempt for MS purposes)
            // - MS net operating loss deduction (5-year carryforward)
            // - Certain dividend income (dividend received deduction)

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.ms_municipal_interest;
            // subtractions += result.ms_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // MS uses graduated rates: 3%, 4%, 5%
            double taxable_income = apportionment.state_taxable_income;
            double tax = 0.0;

            // Tier 1: 3% on first $5,000
            if (taxable_income > 0) {
              double tier1_income = Math.min(taxable_income, apportionment.ms_bracket_tier1);
              tax += tier1_income * apportionment.ms_tax_rate_tier1;
            }

            // Tier 2: 4% on next $5,000 ($5,001-$10,000)
            if (taxable_income > apportionment.ms_bracket_tier1) {
              double tier2_income = Math.min(
                taxable_income - apportionment.ms_bracket_tier1,
                apportionment.ms_bracket_tier2 - apportionment.ms_bracket_tier1
              );
              tax += tier2_income * apportionment.ms_tax_rate_tier2;
            }

            // Tier 3: 5% on income over $10,000
            if (taxable_income > apportionment.ms_bracket_tier2) {
              double tier3_income = taxable_income - apportionment.ms_bracket_tier2;
              tax += tier3_income * apportionment.ms_tax_rate_tier3;
            }

            apportionment.state_tax = tax;

            // Subtract MS state credits
            // MS offers various credits: jobs creation, investment,
            // R&D, film production, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
